const express = require('express');
const app = express();

// Body parsing with limits to prevent abuse
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Basic rate limiting using a simple in-memory store
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // Max requests per window

const rateLimitMiddleware = (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  // Clean up old entries
  if (requestCounts.size > 1000) {
    // Simple cleanup if we have too many entries
    const cleanupThreshold = now - (RATE_LIMIT_WINDOW * 2);
    for (const [key, value] of requestCounts) {
      if (value.timestamp < cleanupThreshold) {
        requestCounts.delete(key);
      }
    }
  }

  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  // Reset counter if outside the window
  if (now - record.timestamp > RATE_LIMIT_WINDOW) {
    record.count = 0;
    record.timestamp = now;
  }

  record.count++;
  requestCounts.set(ip, record);

  if (record.count > RATE_LIMIT_MAX) {
    return res.status(429).json({ 
      status: 'error', 
      message: 'Too many requests from this IP, please try again later' 
    });
  }

  next();
};

// Use rate limiting on API routes
app.use('/api', rateLimitMiddleware);

// Security headers
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit cache
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');

  next();
});

// Input validation utility
const validateUserId = (id) => {
  const numId = parseInt(id, 10);
  return !isNaN(numId) && numId > 0;
};

// Health check with proper error handling
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with error handling and input validation
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Check if a specific user is requested
    const userId = req.query.id;
    if (userId) {
      // Input validation
      if (!validateUserId(userId)) {
        return res.status(400).json({ 
          status: 'error', 
          message: 'Invalid user ID format' 
        });
      }

      const user = users.find(u => u.id === parseInt(userId));
      if (!user) {
        return res.status(404).json({ 
          status: 'error', 
          message: 'User not found' 
        });
      }

      return res.status(200).json(user);
    }

    res.status(200).json(users);
  } catch (error) {
    console.error('Error in /users route:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Can't find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  res.status(500).json({
    status: 'error',
    message: 'Something went wrong!' // Generic message to avoid information disclosure
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

