    const idNum = parseInt(id, 10);
    if (isNaN(idNum) || idNum <= 0) {
      return res.status(400).json({
        error: 'Invalid ID parameter. Must be a positive integer.',
      });
    }
    // Store validated ID in request object
    req.validatedId = idNum;
  }
  next();
};

// Enhanced health check with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Simulated data - in a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Input validation for query parameters
    const { limit, offset } = req.query;

    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a positive integer between 1 and 100.',
        });
      }
      // Apply limit
      users.length = Math.min(users.length, limitNum);
    }

    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
      // Apply offset
      const startIndex = Math.min(offsetNum, users.length);
      users.splice(0, startIndex);
    }

    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error while fetching users',
    });
  }
});

// Enhanced error handling middleware
