// Suggested improved version of app.js
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.hidePoweredBy()); // Removes X-Powered-By header

// Enable CORS with security restrictions
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Body parsing with size limits for security
app.use(express.json({ 
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (id && isNaN(parseInt(id))) {
    return res.status(400).json({ 
      error: 'Invalid ID format. ID must be a number.' 
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed' 
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', async (req, res) => {
  try {
    // Simulate data access with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Add query parameter filtering with validation
    const { name } = req.query;
    let filteredUsers = users;

    if (name) {
      // Input validation and sanitization
      const sanitizedName = String(name).trim().toLowerCase();
      if (sanitizedName.length < 2) {
        return res.status(400).json({
          error: 'Name filter must be at least 2 characters long'
        });
      }
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedName)
      );
    }

    res.json({
      count: filteredUsers.length,
      data: filteredUsers
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Prevent stack traces in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal server error'
    });
  }

  // Include stack trace in development
  res.status(500).json({
    error: 'Internal server error',
    message: error.message,
    stack: error.stack
  });
});

// Use environment variable for port
const PORT = process.env.PORT || 3000;

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;
```

## Additional Dependencies to Install

```bash
npm install express-rate-limit helmet cors dotenv
npm install --save-dev nodemon
```

## Environment Configuration

Create a `.env` file:
```
PORT=3000
NODE_ENV=development
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:8080
```

## Key Security Improvements

1. **Helmet.js**: Adds security headers (XSS protection, frame options, etc.)
2. **Rate limiting**: Prevents abuse and DDoS attacks
3. **Input validation**: Validates and sanitizes all inputs
4. **Error handling**: Proper error middleware prevents information disclosure
5. **CORS**: Restricts cross-origin requests
6. **Body size limits**: Prevents large payloads that could cause denial of service
7. **Environment variables**: Externalizes configuration
8. **Graceful shutdown**: Properly handles process termination

These changes significantly improve the security posture of the application while adding proper error handling and input validation.

