const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : true // Allow all in development
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Validate and sanitize input middleware
const validateUserId = (req, res, next) => {
  const userId = req.params.id;

  // Input validation
  if (userId) {
    const id = parseInt(userId, 10);
    if (isNaN(id) || id <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID. ID must be a positive integer.',
        timestamp: new Date().toISOString()
      });
    }
    // Sanitize by using the parsed integer
    req.params.id = id;
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // In a real app, you might check database connectivity here
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', validateUserId, (req, res) => {
  try {
    // In a real app, this would query a database
    // Add pagination and filtering based on query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Max 100 per page

    if (page < 1) {
      return res.status(400).json({
        error: 'Page number must be greater than 0',
        timestamp: new Date().toISOString()
      });
    }

    if (limit < 1) {
      return res.status(400).json({
        error: 'Limit must be greater than 0',
        timestamp: new Date().toISOString()
      });
    }

    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = mockUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: mockUsers.length,
        pages: Math.ceil(mockUsers.length / limit)
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred',
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The requested endpoint '${req.method} ${req.url}' does not exist.`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Don't leak sensitive error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(error.status || 500).json({
    error: isProduction ? 'Internal server error' : error.message,
    message: isProduction 
      ? 'An unexpected error occurred' 
      : error.stack,
    timestamp: new Date().toISOString()
  });
});

// Graceful shutdown
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
  server.close(() => {
    process.exit(1);
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

