const sanitize = require('sanitize-html');

/**
 * Sanitize input data to prevent XSS attacks
 */
exports.sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return sanitize(input, {
      allowedTags: [],
      allowedAttributes: {}
    });
  }

  if (typeof input === 'object' && input !== null) {
    const sanitized = {};
    for (const [key, value] of Object.entries(input)) {
      sanitized[key] = exports.sanitizeInput(value);
    }
    return sanitized;
  }

  return input;
};

/**
 * Validate email format
 */
exports.validateEmail = (email) => {
  const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
  return emailRegex.test(email);
};

/**
 * Validate required fields
 */
exports.validateRequired = (obj, requiredFields) => {
  const errors = [];

  requiredFields.forEach(field => {
    if (!obj[field] || obj[field].toString().trim() === '') {
      errors.push(`Missing required field: ${field}`);
    }
  });

  return errors;
};

/**
 * Centralized error handler middleware
 */
exports.errorHandler = (err, req, res, next) => {
  // Log the error (in production, use a logging service)
  console.error('Error:', err);

  // Hide internal server errors from clients
  const statusCode = err.statusCode || 500;

  // Don't leak stack traces in production
  const response = {
    success: false,
    message: statusCode === 500 ? 'Internal server error' : err.message
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV === 'development' && statusCode !== 500) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
};

/**
 * Handle 404 errors
 */
exports.notFound = (req, res, next) => {
  const error = new Error(`Route ${req.originalUrl} not found`);
  error.statusCode = 404;
  next(error);
};

