const express = require('express');
const app = express();

// Security headers middleware (lightweight implementation)
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size
  if (req.headers['content-length'] && parseInt(req.headers['content-length']) > 10240) {
    return res.status(413).json({ error: 'Payload too large' });
  }

  next();
});

// Body parsing with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Simple rate limiting (in-memory)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // max requests per window

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const record = requestCounts.get(ip) || { count: 0, firstRequest: now };

  // Clean old records (outside window)
  if (now - record.firstRequest > RATE_LIMIT_WINDOW) {
    requestCounts.set(ip, { count: 1, firstRequest: now });
  } else {
    record.count++;
    requestCounts.set(ip, record);

    if (record.count > RATE_LIMIT_MAX) {
      return res.status(429).json({ 
        error: 'Too many requests from this IP, please try again later.' 
      });
    }
  }

  next();
});

// Input sanitization middleware
app.use((req, res, next) => {
  // Simple sanitize function to remove potential malicious query parameters
  const sanitizeObject = (obj) => {
    if (!obj || typeof obj !== 'object') return obj;

    const sanitized = {};
    for (let [key, value] of Object.entries(obj)) {
      // Strip potentially dangerous characters in keys
      if (typeof key === 'string') {
        key = key.replace(/[\<>'"{}()\[\];]/g, '');
      }

      // Deep sanitize values
      if (typeof value === 'object') {
        sanitized[key] = sanitizeObject(value);
      } else if (typeof value === 'string') {
        // Basic XSS protection
        value = value.replace(/<script[^>]*>.*?<\/script>/gi, '')
                    .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
                    .replace(/javascript:/gi, '')
                    .replace(/vbscript:/gi, '');
        sanitized[key] = value;
      } else {
        sanitized[key] = value;
      }
    }
    return sanitized;
  };

  // Sanitize query parameters
  if (req.query) {
    req.query = sanitizeObject(req.query);
  }

  next();
});

// Health check endpoint with error handling
app.get('/health', (req, res) => {
  try {
    // Input validation
    if (req.query && Object.keys(req.query).length > 5) {
      return res.status(400).json({
        error: 'Too many query parameters'
      });
    }

    // Validate individual query parameters
    for (let [key, value] of Object.entries(req.query)) {
      if (typeof value === 'string' && value.length > 100) {
        return res.status(400).json({
          error: `Query parameter ${key} exceeds maximum length`
        });
      }
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Users endpoint with pagination and validation
app.get('/users', (req, res) => {
  try {
    // Input validation
    let page = 1;
    let limit = 10;

    if (req.query.page !== undefined) {
      page = parseInt(req.query.page);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({
          error: 'Page must be a positive integer'
        });
      }
    }

    if (req.query.limit !== undefined) {
      limit = parseInt(req.query.limit);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Limit must be a positive integer between 1 and 100'
        });
      }
    }

    // Mock data (in real app, this would come from a database)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Calculate pagination
    const total = mockUsers.length;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const paginatedUsers = mockUsers.slice(startIndex, endIndex);

    // Build response with pagination info
    const response = {
      results: paginatedUsers,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(total / limit),
        totalUsers: total,
        hasNext: endIndex < total,
        hasPrev: startIndex > 0
      }
    };

    res.json(response);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Cannot ${req.method} ${req.originalUrl} - Route not found`
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

