    if (req.query && Object.keys(req.query).length > 5) {
      logger.warn('Health check with excessive query parameters', { ip: req.ip, params: req.query });
      return res.status(400).json({ 
        error: 'Invalid request', 
        message: 'Too many query parameters' 
      });
