app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (!id) {
    return res.status(400).json({
      error: 'ID parameter is required'
    });
  }

  // Check if ID is a valid number
  const idNumber = parseInt(id, 10);
  if (isNaN(idNumber) || idNumber <= 0) {
    return res.status(400).json({
      error: 'ID must be a positive integer'
    });
  }

  // Attach validated ID to request for downstream use
  req.validatedId = idNumber;
  next();
};

// Rate limiting (basic in-memory implementation)
const requestRateLimit = new Map();
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const MAX_REQUESTS = 100; // max requests per window

app.use((req, res, next) => {
  const clientIp = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean up old entries
  for (const [ip, data] of requestRateLimit.entries()) {
    if (now - data.windowStart > RATE_LIMIT_WINDOW) {
      requestRateLimit.delete(ip);
    }
  }

  if (!requestRateLimit.has(clientIp)) {
    requestRateLimit.set(clientIp, { count: 1, windowStart: now });
    next();
    return;
  }

  const clientData = requestRateLimit.get(clientIp);

  if (clientData.count >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Rate limit exceeded. Please try again later.'
    });
  }

  clientData.count++;
  next();
});

