const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests
app.use(limiter);

// Middleware for parsing JSON with size limits
app.use(express.json({
  limit: '10kb' // Prevent large payload attacks
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const allowedFields = ['verbose', 'detailed'];
    const queryKeys = Object.keys(req.query);

    for (const key of queryKeys) {
      if (!allowedFields.includes(key)) {
        return res.status(400).json({
          error: `Invalid query parameter: ${key}`,
          allowed: allowedFields
        });
      }
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    };

    // Add detailed info if requested
    if (req.query.verbose === 'true' || req.query.detailed === 'true') {
      healthData.process = {
        uptime: process.uptime(),
        memory: process.memoryUsage()
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { page, limit, sort } = req.query;

    // Validate pagination parameters
    let pageNum = 1;
    let limitNum = 10;

    if (page !== undefined) {
      pageNum = parseInt(page, 10);
      if (isNaN(pageNum) || pageNum < 1) {
        return res.status(400).json({
          error: 'Page parameter must be a positive integer'
        });
      }

      // Reasonable limits
      if (pageNum > 1000) {
        return res.status(400).json({
          error: 'Page parameter exceeds maximum allowed value (1000)'
        });
      }
    }

    if (limit !== undefined) {
      limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Limit parameter must be between 1 and 100'
        });
      }
    }

    // Validate sort parameter
    const allowedSorts = ['name', 'email', 'id', 'created_at'];
    if (sort !== undefined && !allowedSorts.includes(sort)) {
      return res.status(400).json({
        error: `Invalid sort parameter. Allowed values: ${allowedSorts.join(', ')}`
      });
    }

    // Mock data (in real app, would come from database)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date('2023-01-01') },
      { id: 2, name: 'Bob', email: 'bob@example.com', created_at: new Date('2023-01-02') },
    ];

    // Sort data if requested
    let usersData = [...mockUsers];
    if (sort) {
      usersData.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    // Apply pagination
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = usersData.slice(startIndex, startIndex + limitNum);

    // Return paginated response
    res.json({
      users: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: mockUsers.length,
        pages: Math.ceil(mockUsers.length / limitNum)
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Hide internal details in production
  const errorResponse = {
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  };

  // Add detailed error info in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(500).json(errorResponse);
});

// Handle 404 - Resource not found
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

