// Simple rate limiting mechanism
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const clientIP = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) {
    for (const [ip, data] of requestCounts) {
      if (now - data.timestamp > RATE_LIMIT_WINDOW) {
        requestCounts.delete(ip);
      }
    }
  }

  const record = requestCounts.get(clientIP) || { count: 0, timestamp: now };

  // Reset counter if outside window
  if (now - record.timestamp > RATE_LIMIT_WINDOW) {
    record.count = 0;
    record.timestamp = now;
  }

  record.count++;
  requestCounts.set(clientIP, record);

  if (record.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests, please try again later'
    });
  }

  next();
});

// Health check endpoint with error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters
    const allowedFields = ['verbose', 'detailed'];
    const queryKeys = Object.keys(req.query);

    for (const key of queryKeys) {
      if (!allowedFields.includes(key)) {
        return res.status(400).json({
          error: `Invalid query parameter: ${key}`,
          allowed: allowedFields
        });
      }
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    };

    // Add detailed info if requested
    if (req.query.verbose === 'true' || req.query.detailed === 'true') {
      healthData.process = {
        uptime: process.uptime()
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { page, limit } = req.query;

    // Validate pagination parameters
    let pageNum = 1;
    let limitNum = 10;

    if (page !== undefined) {
      pageNum = parseInt(page, 10);
      if (isNaN(pageNum) || pageNum < 1) {
        return res.status(400).json({
          error: 'Page parameter must be a positive integer'
        });
      }

      // Reasonable limits
      if (pageNum > 1000) {
        return res.status(400).json({
          error: 'Page parameter exceeds maximum allowed value (1000)'
        });
      }
    }

    if (limit !== undefined) {
      limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Limit parameter must be between 1 and 100'
        });
      }
    }

    // Mock data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = mockUsers.slice(startIndex, startIndex + limitNum);

    // Return paginated response
    res.json({
      users: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: mockUsers.length,
        pages: Math.ceil(mockUsers.length / limitNum)
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Handle 404 - Resource not found
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  res.status(500).json({
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

